import sys

def main():
    try:
        line = sys.stdin.readline()
        if not line:
            print("Invalid Salary")
            return
        base_salary = int(line.strip())
        if base_salary <= 0:
            print("Invalid Salary")
        else:
            bonus = base_salary // 5
            total = base_salary + bonus
            print(f"Total Salary: {total}")
    except:
        print("Invalid Salary")

if __name__ == "__main__":
    main()
